// Fetches current weather for all 140 Kerala Assembly seats in seats.json
// and writes the result to weatherData.json, which the page reads at load
// time. Same pattern as ../mangalaExpress/scrapeWeather.js — a snapshot
// generated by hand-running this script, not a live per-visitor API call.
// The page's Refresh button does the same fetch in the browser.
//
// Run manually from this folder: `node scrapeWeather.js` (about 2.5
// minutes: 140 calls, throttled to stay under the free-tier limit).
//
// Keyed by `no` — the seat's official constituency number (1 Manjeshwaram
// .. 140 Neyyattinkara), unique and stable.

const fs = require("fs");
const path = require("path");

// Same free-tier key every other scrapeWeather.js in this app already
// ships to the browser — reusing it here doesn't expose anything new.
const API_KEY = "39a9a737b07b4b703e3d1cd1e231eedc";
const DELAY_MS = 1100; // keeps us under OpenWeather's free-tier 60-calls/minute limit

const SEATS_PATH = path.join(__dirname, "seats.json");
const OUTPUT_PATH = path.join(__dirname, "weatherData.json");

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function fetchWeather(seat) {
  const url =
    `https://api.openweathermap.org/data/2.5/weather` +
    `?lat=${seat.lat}&lon=${seat.lon}&units=metric&appid=${API_KEY}`;

  const response = await fetch(url);
  const data = await response.json();

  if (!response.ok) {
    throw new Error(data.message || `Request failed (${response.status})`);
  }

  return {
    temp: data.main.temp,
    description: data.weather[0] ? data.weather[0].description : "",
    timezone: data.timezone,
    sunrise: data.sys.sunrise,
    sunset: data.sys.sunset,
    dayLengthSeconds: data.sys.sunset - data.sys.sunrise,
  };
}

async function main() {
  const seats = JSON.parse(fs.readFileSync(SEATS_PATH, "utf8"));
  const existing = fs.existsSync(OUTPUT_PATH)
    ? JSON.parse(fs.readFileSync(OUTPUT_PATH, "utf8"))
    : { generatedAt: null, byNo: {} };

  const byNo = { ...existing.byNo };
  let failures = 0;

  for (const seat of seats) {
    process.stdout.write(`#${seat.no} ${seat.constituency}, ${seat.district}... `);
    try {
      byNo[seat.no] = await fetchWeather(seat);
      console.log(`ok, ${byNo[seat.no].temp.toFixed(1)}°C`);
    } catch (err) {
      // Keep whatever this seat had from the last successful scrape
      // rather than blanking its row out over one flaky request.
      failures += 1;
      console.log(`FAILED (${err.message}) — keeping previous data`);
    }
    await sleep(DELAY_MS);
  }

  const output = { generatedAt: Math.floor(Date.now() / 1000), byNo };
  fs.writeFileSync(OUTPUT_PATH, JSON.stringify(output, null, 2) + "\n");
  console.log(`\nWrote ${Object.keys(byNo).length} entries to ${OUTPUT_PATH}` +
    (failures ? ` (${failures} failed this run, old data kept for those)` : ""));
}

main();
